const conf = loadSync();
```

Usage
```ts
import { stringify } from "@ende/dotenv/stringify";
import { assertEquals } from "@ende/assert";

const object = { GREETING: "hello world" };
assertEquals(stringify(object), "GREETING='hello world'");
```

